const WEEK_DAYS = ["شنبه", "یکشنبه", "دوشنبه", "سه‌شنبه", "چهارشنبه", "پنجشنبه", "جمعه"];

// ============================
// تقویم شمسی (جلالی) — تبدیل تاریخ بدون نیاز به کتابخانه خارجی
// الگوریتم استاندارد تبدیل میلادی↔شمسی (بر پایه محاسبات نجومی رایج)
// ============================
function jdiv(a: number, b: number) {
  return Math.floor(a / b);
}
function jmod(a: number, b: number) {
  return a - Math.floor(a / b) * b;
}
function gregorianToJdn(gy: number, gm: number, gd: number) {
  const a = jdiv(14 - gm, 12);
  const y = gy + 4800 - a;
  const m = gm + 12 * a - 3;
  return gd + jdiv(153 * m + 2, 5) + 365 * y + jdiv(y, 4) - jdiv(y, 100) + jdiv(y, 400) - 32045;
}
function jdnToGregorian(jdn: number) {
  let a = jdn + 32044;
  const b = jdiv(4 * a + 3, 146097);
  a = a - jdiv(146097 * b, 4);
  const c = jdiv(4 * a + 3, 1461);
  a = a - jdiv(1461 * c, 4);
  const m = jdiv(5 * a + 2, 153);
  const gd = a - jdiv(153 * m + 2, 5) + 1;
  const gm = m + 3 - 12 * jdiv(m, 10);
  const gy = 100 * b + c - 4800 + jdiv(m, 10);
  return { gy, gm, gd };
}
const JALALI_BREAKS = [
  -61, 9, 38, 199, 426, 686, 756, 818, 1111, 1181, 1210, 1635, 2060, 2097, 2192, 2262, 2324, 2394,
  2456, 3178,
];
function jalCal(jy: number) {
  const bl = JALALI_BREAKS.length;
  const gy = jy + 621;
  let leapJ = -14;
  let jp = JALALI_BREAKS[0];
  let jump = 0;
  for (let i = 1; i < bl; i += 1) {
    const jm = JALALI_BREAKS[i];
    jump = jm - jp;
    if (jy < jm) break;
    leapJ = leapJ + jdiv(jump, 33) * 8 + jdiv(jmod(jump, 33), 4);
    jp = jm;
  }
  let n = jy - jp;
  leapJ = leapJ + jdiv(n, 33) * 8 + jdiv(jmod(n, 33) + 3, 4);
  if (jmod(jump, 33) === 4 && jump - n === 4) leapJ += 1;
  const leapG = jdiv(gy, 4) - jdiv((jdiv(gy, 100) + 1) * 3, 4) - 150;
  const march = 20 + leapJ - leapG;
  if (jump - n < 6) n = n - jump + jdiv(jump, 33) * 33;
  let leap = jmod(jmod(n + 1, 33) - 1, 4);
  if (leap === -1) leap = 4;
  return { leap, gy, march };
}
function jalaliToJdn(jy: number, jm: number, jd: number) {
  const r = jalCal(jy);
  return gregorianToJdn(r.gy, 3, r.march) + (jm - 1) * 31 - jdiv(jm, 7) * (jm - 7) + jd - 1;
}
function jdnToJalali(jdn: number) {
  const gy = jdnToGregorian(jdn).gy;
  let jy = gy - 621;
  const r = jalCal(jy);
  const jdn1f = gregorianToJdn(r.gy, 3, r.march);
  let k = jdn - jdn1f;
  let jm: number, jd: number;
  if (k >= 0) {
    if (k <= 185) {
      jm = 1 + jdiv(k, 31);
      jd = jmod(k, 31) + 1;
      return { jy, jm, jd };
    } else {
      k -= 186;
    }
  } else {
    jy -= 1;
    k += 179;
    if (r.leap === 1) k += 1;
  }
  jm = 7 + jdiv(k, 30);
  jd = jmod(k, 30) + 1;
  return { jy, jm, jd };
}
function gregorianToJalali(gy: number, gm: number, gd: number) {
  return jdnToJalali(gregorianToJdn(gy, gm, gd));
}
function jalaliToGregorian(jy: number, jm: number, jd: number) {
  return jdnToGregorian(jalaliToJdn(jy, jm, jd));
}
function isJalaliLeapYear(jy: number) {
  return jalCal(jy).leap === 1;
}
function daysInJalaliMonth(jy: number, jm: number) {
  if (jm <= 6) return 31;
  if (jm <= 11) return 30;
  return isJalaliLeapYear(jy) ? 30 : 29;
}
const JALALI_MONTHS = [
  "فروردین",
  "اردیبهشت",
  "خرداد",
  "تیر",
  "مرداد",
  "شهریور",
  "مهر",
  "آبان",
  "آذر",
  "دی",
  "بهمن",
  "اسفند",
];
// تبدیل رشته تاریخ ذخیره‌شده به‌صورت میلادی "YYYY-MM-DD" به آبجکت شمسی، برای مقداردهی اولیه فرم
function isoToJalaliParts(iso: string): { jy: number; jm: number; jd: number } | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso);
  if (!m) return null;
  return gregorianToJalali(Number(m[1]), Number(m[2]), Number(m[3]));
}
// تبدیل تاریخ شمسی انتخاب‌شده در فرم به رشته میلادی "YYYY-MM-DD" برای ذخیره در پایگاه‌داده
function jalaliPartsToIso(jy: number, jm: number, jd: number): string {
  const { gy, gm, gd } = jalaliToGregorian(jy, jm, jd);
  return `${String(gy).padStart(4, "0")}-${String(gm).padStart(2, "0")}-${String(gd).padStart(2, "0")}`;
}

// انتخابگر تاریخ شمسی (روز/ماه/سال) — جایگزین اینپوت میلادی مرورگر
function JalaliDatePicker({
  value,
  onChange,
}: {
  value: string; // "YYYY-MM-DD" میلادی یا خالی
  onChange: (isoValue: string) => void;
}) {
  const todayJalali = gregorianToJalali(
    new Date().getFullYear(),
    new Date().getMonth() + 1,
    new Date().getDate(),
  );
  const parts = value ? isoToJalaliParts(value) : null;
  const jy = parts?.jy ?? todayJalali.jy;
  const jm = parts?.jm ?? todayJalali.jm;
  const jd = parts?.jd ?? todayJalali.jd;

  const yearOptions = useMemo(() => {
    const arr: number[] = [];
    for (let y = todayJalali.jy + 2; y >= todayJalali.jy - 10; y -= 1) arr.push(y);
    return arr;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const dayCount = daysInJalaliMonth(jy, jm);
  const dayOptions = useMemo(() => Array.from({ length: dayCount }, (_, i) => i + 1), [dayCount]);

  const emitChange = (nJy: number, nJm: number, nJd: number) => {
    const maxDay = daysInJalaliMonth(nJy, nJm);
    const safeDay = Math.min(nJd, maxDay);
    onChange(jalaliPartsToIso(nJy, nJm, safeDay));
  };

  return (
    <div className="grid grid-cols-3 gap-2">
      <Select value={value ? String(jd) : ""} onValueChange={(v) => emitChange(jy, jm, Number(v))}>
        <SelectTrigger>
          <SelectValue placeholder="روز" />
        </SelectTrigger>
        <SelectContent>
          {dayOptions.map((d) => (
            <SelectItem key={d} value={String(d)}>
              {d}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <Select value={value ? String(jm) : ""} onValueChange={(v) => emitChange(jy, Number(v), jd)}>
        <SelectTrigger>
          <SelectValue placeholder="ماه" />
        </SelectTrigger>
        <SelectContent>
          {JALALI_MONTHS.map((name, idx) => (
            <SelectItem key={name} value={String(idx + 1)}>
              {name}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <Select value={value ? String(jy) : ""} onValueChange={(v) => emitChange(Number(v), jm, jd)}>
        <SelectTrigger>
          <SelectValue placeholder="سال" />
        </SelectTrigger>
        <SelectContent>
          {yearOptions.map((y) => (
            <SelectItem key={y} value={String(y)}>
              {y}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

